    const form = document.getElementById('contactForm');
    const fullName = document.getElementById('fullName');
    const email = document.getElementById('email');
    const phone = document.getElementById('phone');
    const formStatus = document.getElementById('formStatus');

    const validators = {
        fullName: (value) => {
            if (!value.trim()) return 'Full name is required.';
            return '';
        },
        email: (value) => {
            if (!value.trim()) return 'Email address is required.';
            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            if (!emailRegex.test(value)) return 'Please enter a valid email address.';
            return '';
        },
        phone: (value) => {
            if (!value.trim()) return ''; // Optional
            // Regex for (XXX) XXX-XXXX or XXX-XXX-XXXX
            const phoneRegex = /^(\(\d{3}\)\s?|\d{3}-)\d{3}-\d{4}$/;
            if (!phoneRegex.test(value)) return 'Please use the format (XXX) XXX-XXXX or XXX-XXX-XXXX.';
            return '';
        }
    };

    const validateField = (input, validator) => {
        const errorElement = document.getElementById(`${input.id}Error`);
        const errorMessage = validator(input.value);

        if (errorMessage) {
            input.classList.add('invalid');
            input.setAttribute('aria-invalid', 'true');
            errorElement.textContent = errorMessage;
            return false;
        } else {
            input.classList.remove('invalid');
            input.removeAttribute('aria-invalid');
            errorElement.textContent = '';
            return true;
        }
    };

    // Live validation on blur
    fullName.addEventListener('blur', () => validateField(fullName, validators.fullName));
    email.addEventListener('blur', () => validateField(email, validators.email));
    phone.addEventListener('blur', () => validateField(phone, validators.phone));

    form.addEventListener('submit', (e) => {
        e.preventDefault();

        const isNameValid = validateField(fullName, validators.fullName);
        const isEmailValid = validateField(email, validators.email);
        const isPhoneValid = validateField(phone, validators.phone);

        if (isNameValid && isEmailValid && isPhoneValid) {
            formStatus.textContent = 'Thank you! Your message has been sent.';
            formStatus.className = 'form-status success';
            form.reset();

            // Remove validation classes after reset
            [fullName, email, phone].forEach(input => {
                input.classList.remove('invalid');
                input.removeAttribute('aria-invalid');
            });
        } else {
            formStatus.textContent = 'Please correct the errors above.';
            formStatus.className = 'form-status error-message';

            // Focus the first invalid field
            if (!isNameValid) fullName.focus();
            else if (!isEmailValid) email.focus();
            else if (!isPhoneValid) phone.focus();
        }
    });
});
